import json, sys
ids = []
for line in open(sys.argv[1] + '/results/trials.jsonl'):
    if line.strip():
        t = json.loads(line)
        if any(p['id'] == 'no_cross_scope_reads' and not p['passed'] for p in t.get('predicates', [])):
            ids.append(t['trial_id'].split('/', 1)[1])
print('\n'.join(sorted(ids)))
